/**
 * Measure the body weight (`0.0` slim .. `1.0` curvy) baked into an un-shifted
 * head mesh by comparing its neck seam ring against the canonical body seam.
 */
export function detectHeadBaseWeight(positions: ArrayLike<number>): number {
  if (positions.length !== 11761 * 3) return 1.0;
  let d0Sum = 0;
  let d1Sum = 0;
  for (let i = 0; i < NECK_SEAM_HEAD_INDICES.length; i++) {
    const idx = NECK_SEAM_HEAD_INDICES[i] * 3;
    const x = positions[idx];
    const y = positions[idx + 1];
    const z = positions[idx + 2];
    const o = i * 3;
    d0Sum += Math.hypot(x - SEAM_POS_0[o], y - SEAM_POS_0[o + 1], z - SEAM_POS_0[o + 2]);
    d1Sum += Math.hypot(x - SEAM_POS_1[o], y - SEAM_POS_1[o + 1], z - SEAM_POS_1[o + 2]);
  }
  const denom = d0Sum + d1Sum;
  if (denom < 1e-6) return 1.0;
  return d0Sum / denom;
}
